//! Cargo-driven `usetup.exe` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is usetup-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/base/setup/usetup",
        "base/setup/usetup",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/include/reactos/drivers",
    ];
    let rc_flags: &[&str] = &[
        "-DLANGUAGE_AF_ZA",
        "-DLANGUAGE_AR_AE",
        "-DLANGUAGE_AR_BH",
        "-DLANGUAGE_AR_DZ",
        "-DLANGUAGE_AR_EG",
        "-DLANGUAGE_AR_IQ",
        "-DLANGUAGE_AR_JO",
        "-DLANGUAGE_AR_KW",
        "-DLANGUAGE_AR_LB",
        "-DLANGUAGE_AR_LY",
        "-DLANGUAGE_AR_MA",
        "-DLANGUAGE_AR_OM",
        "-DLANGUAGE_AR_QA",
        "-DLANGUAGE_AR_SA",
        "-DLANGUAGE_AR_SY",
        "-DLANGUAGE_AR_TN",
        "-DLANGUAGE_AR_YE",
        "-DLANGUAGE_AZ_AZ",
        "-DLANGUAGE_BE_BY",
        "-DLANGUAGE_BG_BG",
        "-DLANGUAGE_BN_BD",
        "-DLANGUAGE_BN_IN",
        "-DLANGUAGE_CA_ES",
        "-DLANGUAGE_CS_CZ",
        "-DLANGUAGE_DA_DK",
        "-DLANGUAGE_DE_AT",
        "-DLANGUAGE_DE_CH",
        "-DLANGUAGE_DE_DE",
        "-DLANGUAGE_DE_LI",
        "-DLANGUAGE_DE_LU",
        "-DLANGUAGE_DV_MV",
        "-DLANGUAGE_EL_GR",
        "-DLANGUAGE_EN_AU",
        "-DLANGUAGE_EN_BZ",
        "-DLANGUAGE_EN_CA",
        "-DLANGUAGE_EN_CB",
        "-DLANGUAGE_EN_GB",
        "-DLANGUAGE_EN_IE",
        "-DLANGUAGE_EN_JM",
        "-DLANGUAGE_EN_NZ",
        "-DLANGUAGE_EN_PH",
        "-DLANGUAGE_EN_TT",
        "-DLANGUAGE_EN_US",
        "-DLANGUAGE_EN_ZA",
        "-DLANGUAGE_EN_ZW",
        "-DLANGUAGE_EO_AA",
        "-DLANGUAGE_ES_AR",
        "-DLANGUAGE_ES_BO",
        "-DLANGUAGE_ES_CL",
        "-DLANGUAGE_ES_CO",
        "-DLANGUAGE_ES_CR",
        "-DLANGUAGE_ES_DO",
        "-DLANGUAGE_ES_EC",
        "-DLANGUAGE_ES_ES",
        "-DLANGUAGE_ES_GT",
        "-DLANGUAGE_ES_HN",
        "-DLANGUAGE_ES_MX",
        "-DLANGUAGE_ES_NI",
        "-DLANGUAGE_ES_PA",
        "-DLANGUAGE_ES_PE",
        "-DLANGUAGE_ES_PR",
        "-DLANGUAGE_ES_PY",
        "-DLANGUAGE_ES_SV",
        "-DLANGUAGE_ES_UY",
        "-DLANGUAGE_ES_VE",
        "-DLANGUAGE_ET_EE",
        "-DLANGUAGE_EU_ES",
        "-DLANGUAGE_FA_IR",
        "-DLANGUAGE_FI_FI",
        "-DLANGUAGE_FO_FO",
        "-DLANGUAGE_FR_BE",
        "-DLANGUAGE_FR_CA",
        "-DLANGUAGE_FR_CH",
        "-DLANGUAGE_FR_FR",
        "-DLANGUAGE_FR_LU",
        "-DLANGUAGE_FR_MC",
        "-DLANGUAGE_GL_ES",
        "-DLANGUAGE_GU_IN",
        "-DLANGUAGE_HE_IL",
        "-DLANGUAGE_HI_IN",
        "-DLANGUAGE_HR_HR",
        "-DLANGUAGE_HU_HU",
        "-DLANGUAGE_HY_AM",
        "-DLANGUAGE_ID_ID",
        "-DLANGUAGE_IS_IS",
        "-DLANGUAGE_IT_CH",
        "-DLANGUAGE_IT_IT",
        "-DLANGUAGE_JA_JP",
        "-DLANGUAGE_KA_GE",
        "-DLANGUAGE_KK_KZ",
        "-DLANGUAGE_KN_IN",
        "-DLANGUAGE_KOK_IN",
        "-DLANGUAGE_KO_KR",
        "-DLANGUAGE_KY_KG",
        "-DLANGUAGE_LT_LT",
        "-DLANGUAGE_LV_LV",
        "-DLANGUAGE_MK_MK",
        "-DLANGUAGE_MN_MN",
        "-DLANGUAGE_MR_IN",
        "-DLANGUAGE_MS_BN",
        "-DLANGUAGE_MS_MY",
        "-DLANGUAGE_MY_MM",
        "-DLANGUAGE_NL_BE",
        "-DLANGUAGE_NL_NL",
        "-DLANGUAGE_NN_NO",
        "-DLANGUAGE_PA_IN",
        "-DLANGUAGE_PL_PL",
        "-DLANGUAGE_PT_BR",
        "-DLANGUAGE_PT_PT",
        "-DLANGUAGE_RM_CH",
        "-DLANGUAGE_RO_RO",
        "-DLANGUAGE_RU_RU",
        "-DLANGUAGE_SA_IN",
        "-DLANGUAGE_SK_SK",
        "-DLANGUAGE_SL_SI",
        "-DLANGUAGE_SQ_AL",
        "-DLANGUAGE_SR_SP",
        "-DLANGUAGE_SV_FI",
        "-DLANGUAGE_SV_SE",
        "-DLANGUAGE_SW_KE",
        "-DLANGUAGE_SYR_SY",
        "-DLANGUAGE_TA_IN",
        "-DLANGUAGE_TE_IN",
        "-DLANGUAGE_TH_TH",
        "-DLANGUAGE_TR_TR",
        "-DLANGUAGE_TT_TA",
        "-DLANGUAGE_UK_UA",
        "-DLANGUAGE_UR_PK",
        "-DLANGUAGE_UZ_UZ",
        "-DLANGUAGE_VI_VN",
        "-DLANGUAGE_WA_BE",
        "-DLANGUAGE_ZH_CN",
        "-DLANGUAGE_ZH_HK",
        "-DLANGUAGE_ZH_MO",
        "-DLANGUAGE_ZH_SG",
        "-DLANGUAGE_ZH_TW",
    ];
    let rc_defines: &[&str] = &["WINVER=0x502", "_WIN32_WINNT=0x502"];

    let (target_json, entry) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_NtProcessStartup@4"),
        "x86_64" => ("x86_64-pc-windows-gnu", "NtProcessStartup"),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "NtProcessStartup"),
        o => panic!("usetup-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "engine:c:zlib_solo", "engine:chkstk", "import:setuplib", "import:ntdll", "engine:inflib_rust"],
        "x86_64" => &["body", "engine:c:zlib_solo", "engine:chkstk", "import:setuplib", "import:ntdll", "engine:inflib_rust"],
        "aarch64" => &["body", "engine:c:zlib_solo", "engine:chkstk", "import:setuplib", "import:ntdll", "engine:inflib_rust"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("usetup-rust")
        .rc("base/setup/usetup/usetup.rc", rc_includes, rc_flags, rc_defines)
        .import_lib("base/setup/lib/setuplib.spec", "setuplib.dll", "setuplib")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .link(ModuleKind::Win32Exe {
            entry: entry.into(),
            subsystem: "native:5.01".into(),
        });
}
